def compromis(journal, seuil):
    echecs = {}
    comptes = set()
    for ligne in journal:
        date, heure, statut, compte, ip = ligne.split()
        if statut == "ECHEC":
            echecs[ip] = echecs.get(ip, 0) + 1
        elif statut == "SUCCES" and echecs.get(ip, 0) >= seuil:
            comptes.add(compte)
    return sorted(comptes)

def respecte_321(copies):
    supports = {c["support"] for c in copies}
    return len(copies) >= 3 and len(supports) >= 2 and any(c["lieu"] != "bureau" for c in copies)

def audit(donnees):
    constats = []
    pirates = compromis(donnees["journal"], 3)
    if pirates:
        constats.append((25, "comptes compromis : " + ", ".join(pirates)))
    n = len([nom for nom, mdp in donnees["comptes"].items() if evaluer(mdp, donnees["interdits"]) != "acceptable"])
    if n:
        constats.append((min(5, n) * 3, "mots de passe faibles : " + str(n)))
    if not respecte_321(donnees["copies"]):
        constats.append((15, "sauvegardes non conformes à 3-2-1"))
    if not constats:
        return ["aucun constat"]
    constats.sort(key=lambda c: (-c[0], c[1]))
    return ["[" + niveau(score) + "] " + texte for score, texte in constats]
